#!/usr/bin/env python3
"""Turn 35 Wave 69: THE DLL SEASON FORMAT (extra time vs draws, and the fact that it alternates),
the red-card and shootout rules, the penalty technique, the presentation layer, and the
competitive settings profile.

Wave 69's centrepiece changes the tier-camping arithmetic: DLL seasons ALTERNATE between a
draw-allowed format and an extra-time format, the game announces which at kick-off, and the
corpus's camping rule ("win 4-5 matches, quit the rest") silently assumes draws are bankable.
In an extra-time season they are not.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w69')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_match=new_ev("r/DreamLeagueSoccer 1071e3e (9 Jan 2023, DLL extra time vs draws by season), 1k1g6pe (17 Apr 2025, the five-red-card rule and the advantage-play exploit), 1jmtcwh (29 Mar 2025, shootouts and the penalty technique), 1s5aqel (27 Mar 2026, penalty difficulty), 14ustvs (the run-up animation count), 1b9ae0w (8 Mar 2024, the DLS23 run-up tell and the pause exploit), 1qpe0dp (28 Jan 2026, the competitive settings profile), 1phcvdv (8 Dec 2025, the DLS26 one-week review), App Store DLS26 version history v13.040 (17 Dec 2025) and v13.050 (15 Jan 2026), APKMirror v13.040 release notes, fifaworldcupnews DLS26 features (23 Jul 2026, broadcast cameras, pre-match tracksuits, Turkish/Arabic commentary), sportsdunia DLS26 best settings (3 Mar 2026), eslamgaming visual-evolution (23 Mar 2026, dynamic commentary and crowd) and DLS25-vs-26 (20 Apr 2026, lighting and weather), appitika (3-minute halves), mokoweb v13.430 (dressing-room camera), thesoccerera (pre-match warm-up cutscenes)",
    "THE DLL SEASON FORMAT, THE RED-CARD AND SHOOTOUT RULES, THE PENALTY TECHNIQUE, THE PRESENTATION LAYER, AND THE COMPETITIVE SETTINGS PROFILE. (1) THE DLL SEASON FORMAT ALTERNATES - the wave's centrepiece. A player reports a tier-8 season finale going to extra time after a 1-1, and the thread explains: 'some tiers have extra time some do not I don't know why, it usually says at the beginning of the match if it will go to extra time if tied', and decisively 'DLS switches between Extra Time and Draw after every season, so this season is Extra Time and next season, i.e. after 10 days, the match format will again be draws and it will repeat like this.' So DLL runs on 10-day seasons whose FORMAT ALTERNATES between draw-allowed and extra-time-mandatory, and the game announces which at kick-off. THIS CHANGES THE CAMPING ARITHMETIC: the corpus's rule to 'win 4-5 matches (12-15 points) and quit the rest' silently assumes draws are bankable - in an extra-time season a draw is not a result, it is a coin-flip you must play out. (2) FIVE RED CARDS ENDS THE MATCH: 'a game ends early in football if one team gets 5 players sent off. This rule exists in Dream League Soccer as well: If you get 5 red cards, the match usually automatically ends and you lose.' (3) THE ADVANTAGE-PLAY EXPLOIT, recorded as a curiosity and NOT as advice: the five-card check fires only when play is interrupted by the foul. 'if you foul a player, but the ref gives advantage, you get carded only when the game is interrupted for the next time. But when you receive the card retroactively, DLS never checks how many red cards have been given.' One player reached a shootout with a keeper and two outfield players. (4) FEWER THAN THE REQUIRED PLAYERS FOR A SHOOTOUT IS AN AUTOMATIC LOSS: 'the game probably noticed that I had less than 5 players available for the penalty shootout, so I got an automatic loss before the shootout could start.' (5) THE PENALTY TECHNIQUE, the most specific on record: 'low C press on any side and A slightly left,right with medium press also worked great for me against AI, Penalties in DLL are not that hard, I score 85-90% of penalties in DLL and 70-80% in shootouts with A most times, B sometimes.' Against that, a dissenting player reports missing 80-90% with the A button and scoring only with B or C. (6) CAREER-MODE PENALTIES MAY BE PREDETERMINED: 'career mode pens are fixed. Whether the keeper saves it or not is kinda decided before you kick the ball' - repeated across threads, C4, but consistent with the shootout-futility reports. (7) THE RUN-UP TELL, AND ITS LOSS: 'In the DLS23 you could tell which way your opponent was going based on their run up. They had 6 different animations that would tell you which way they would shoot. Saving penalties became way too easy... However now the animations are mostly random. Some are still consistent so keep track of which ones go where.' A second source puts the count at 'around 10' run-ups, 'so if you memorize them you can save 90% of them'. (8) THE PAUSE-AND-READ TRICK WORKS IN CAREER ONLY: 'when they shoot, the ball is flying towards goal, pause the game and close it after seeing the direction. then go back into game when they shoot the pen it shld be same direction 90 percent of the time' - and the correction: 'how do you pause during penalties? It's online mode. Only possible in career mode.' (9) THE EXTRA-TIME LENGTH SUSPICION, and a direct tension with the official line: a widely-reported complaint that 'extra time running for almost as long as the half when you're in front, and for WAY less time when you're behind', plus 'It no longer tells you how much extra time there is at the end of the halves.' FTG officially states 'there are no additional overlaid controls to manage the difficulty experience', so this is recorded as a SUSPECTED asymmetry - the corpus's own official matchmaking finding says it should not exist. (10) THE PRESENTATION LAYER: 'New broadcast-style camera angles and improved cinematics'; a NEW PRE-MATCH PRESENTATION in which 'players now walk out wearing warm-up/practice tracksuits before kickoff'; commentary now available in TURKISH AND ARABIC for the 25/26 season; 'Enhanced Match Atmosphere - More props, banners, flags, and more'; 'Brand new soundtrack and SFX'; 'Improved commentary - Now more accurate with added phrases'; 'New cutscenes - Feel the action on and off the pitch' (all v13.050, 15 Jan); and a Dressing Room Camera to 'check out your team's customized locker room and see player interactions'. Commentary is dynamically generated, not pre-recorded, and 'the crowd noise is dynamic, swelling when your team attacks and quieting during defensive phases'. (11) LIGHTING AND WEATHER: 'Improved dynamic lighting for day and night matches' and 'Environmental Effects: Weather conditions like rain and wind affecting gameplay' - so weather is a gameplay input, not decoration. (12) THE COMPETITIVE SETTINGS PROFILE, from a player: 'Sideline camera, 30% zoom, game directional arrows OFF, radar map ON, names ON, scoreboard ON, kick assist OFF, cross assist OFF, pass assist OFF, basically all assist OFF.' A guide's alternative: Camera Type TV, Camera Distance 80%, Auto Replay Off, Commentary 20%, Music Off, SFX 10%, Haptic Feedback Off. (13) MATCH LENGTH: 'Matches run in real time with a 3-minute half-length by default, but you can speed up or pause the action.' (14) v13.040 (17 Dec 2025) shipped 'Increased squad size - Now with unlimited special players in your club', improved venues, and the launch event 'Kick-Off Stars - Collect special edition Raphinha and Alvarez cards at launch!'",
    "evidence/raw/turn35_w69/EV-483_match_format_and_presentation.html",
    "DLL SEASON FORMAT ALTERNATES: seasons run 10 days and switch between draw-allowed and extra-time-mandatory, announced at kick-off - so the camping rule's assumption that draws are bankable fails in an extra-time season. RED CARDS: five ends the match with an automatic loss; the check only fires when play is interrupted by the foul, so advantage-play cards are retroactive and bypass it (recorded as a curiosity, not advice); fewer than the required players for a shootout is an automatic loss. PENALTIES: low C press on any side plus A slightly left/right with medium press scores 85-90% in DLL and 70-80% in shootouts (one dissenter reports the opposite); career-mode pens may be predetermined; ~10 run-up animations were a readable tell in DLS23 and are mostly random now; the pause-and-read trick works in Career only. EXTRA TIME: widely reported to run longer when leading and shorter when behind, and DLS26 removed the extra-time clock - a suspected asymmetry that sits against FTG's official 'no additional overlaid controls' line. PRESENTATION: broadcast cameras, a pre-match walk-out in tracksuits, Turkish and Arabic commentary, more props/banners/flags, a new soundtrack and SFX, new cutscenes, a dressing-room camera, dynamic commentary and crowd noise, dynamic day/night lighting, and rain and wind that affect gameplay. SETTINGS: the competitive profile is all assists off with the radar on and a sideline camera at 30% zoom; default half-length is 3 minutes",
    quality="community")

add_claim("THE DLL SEASON FORMAT ALTERNATES: seasons run 10 days and switch between a DRAW-ALLOWED format and an EXTRA-TIME-MANDATORY format - 'DLS switches between Extra Time and Draw after every season, so this season is Extra Time and next season, i.e. after 10 days, the match format will again be draws and it will repeat like this.'", 2, "dll/season-format-alternates", [e_match], notes="CHANGES THE CAMPING ARITHMETIC - draws are not always bankable")
add_claim("Some DLL tiers have extra time and some do not, and the game announces at the start of the match whether a tie will go to extra time.", 2, "dll/extra-time-announced-at-kickoff", [e_match])
add_claim("FIVE RED CARDS ENDS THE MATCH with an automatic loss: 'If you get 5 red cards, the match usually automatically ends and you lose.'", 2, "gameplay/five-red-cards-ends-match", [e_match])
add_claim("The five-red-card check fires only when play is interrupted by the foul - a card given retroactively after the referee plays advantage bypasses the check entirely, which is how one player reached a shootout with a keeper and two outfield players. RECORDED AS A CURIOSITY, NOT AS ADVICE.", 3, "gameplay/advantage-play-card-exploit", [e_match], notes="An exploit - do not farm red cards")
add_claim("Fewer than the required number of players for a penalty shootout is an automatic loss, awarded before the shootout starts.", 2, "gameplay/insufficient-players-for-shootout", [e_match])
add_claim("PENALTY TECHNIQUE: 'low C press on any side and A slightly left,right with medium press also worked great for me against AI' - reported at 85-90% conversion in DLL and 70-80% in shootouts. One dissenter reports missing 80-90% with the A button and scoring only with B or C.", 3, "gameplay/penalty-technique", [e_match])
add_claim("Career-mode penalties may be PREDETERMINED: 'career mode pens are fixed. Whether the keeper saves it or not is kinda decided before you kick the ball.' Repeated across threads; C4 until verified.", 4, "gameplay/career-pens-predetermined", [e_match], notes="Consistent with the shootout-futility reports")
add_claim("Penalty run-ups were a READABLE TELL in DLS23 - 'they had 6 different animations that would tell you which way they would shoot' - but 'now the animations are mostly random. Some are still consistent so keep track of which ones go where.' A second source counts around 10 distinct run-ups.", 3, "gameplay/run-up-animations-mostly-random", [e_match])
add_claim("The pause-and-read penalty trick works in CAREER ONLY: pause while the ball is in flight, note the direction, close and reopen, and the kick repeats the same direction about 90% of the time. You cannot pause in Dream League Live.", 3, "gameplay/pause-read-penalty-career-only", [e_match])
add_claim("EXTRA TIME IS WIDELY SUSPECTED OF RUNNING ASYMMETRICALLY: 'extra time running for almost as long as the half when you're in front, and for WAY less time when you're behind', and DLS26 'no longer tells you how much extra time there is at the end of the halves.' This sits directly against FTG's official 'there are no additional overlaid controls to manage the difficulty experience' - recorded as a suspected asymmetry, not a finding.", 3, "gameplay/extra-time-asymmetry-suspected", [e_match], notes="Tension with the official matchmaking statement - watch for it")
add_claim("DLS26 PRESENTATION: 'New broadcast-style camera angles and improved cinematics', and a new pre-match presentation in which 'players now walk out wearing warm-up/practice tracksuits before kickoff'.", 2, "presentation/broadcast-cameras-and-walkout", [e_match])
add_claim("Commentary is now available in TURKISH AND ARABIC for the 25/26 season, alongside 'improved commentary - now more accurate with added phrases'. Commentary is dynamically generated from the match situation, not pre-recorded.", 2, "presentation/turkish-arabic-commentary", [e_match])
add_claim("DLS26 presentation upgrades: 'Enhanced Match Atmosphere - More props, banners, flags, and more', 'Brand new soundtrack and SFX', 'New cutscenes - Feel the action on and off the pitch' (v13.050, 15 Jan 2026), plus a Dressing Room Camera to 'check out your team's customized locker room and see player interactions'.", 2, "presentation/atmosphere-cutscenes-dressing-room", [e_match])
add_claim("Crowd noise is dynamic - 'swelling when your team attacks and quieting during defensive phases' - so the audio is a genuine possession cue.", 3, "presentation/dynamic-crowd-noise", [e_match])
add_claim("DLS26 has 'improved dynamic lighting for day and night matches' and 'environmental effects: weather conditions like rain and wind affecting gameplay' - weather is a gameplay input, not decoration.", 3, "presentation/weather-affects-gameplay", [e_match])
add_claim("THE COMPETITIVE SETTINGS PROFILE: 'Sideline camera, 30% zoom, game directional arrows OFF, radar map ON, names ON, scoreboard ON, kick assist OFF, cross assist OFF, pass assist OFF, basically all assist OFF.' A guide's alternative is Camera Type TV, Camera Distance 80%, Auto Replay Off, Commentary 20%, Music Off, SFX 10%, Haptic Feedback Off.", 3, "settings/competitive-profile", [e_match])
add_claim("Matches run in real time with a 3-MINUTE HALF-LENGTH by default, and can be sped up or paused.", 2, "gameplay/three-minute-halves", [e_match])
add_claim("v13.040 (17 Dec 2025) shipped 'Increased squad size - Now with unlimited special players in your club', improved venues, and the launch event 'Kick-Off Stars - Collect special edition Raphinha and Alvarez cards at launch!'", 2, "events/kick-off-stars-launch-event", [e_match])

for name in ('EV-483_match_format_and_presentation.html',):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
